class Bts(object):

    @classmethod
    def get_expected_statuses(cls, variant):
        """
        Returns expected values of statuses for given variant.
        :param variant: variant of expected statuses, can be 'onair', 'test', 'blocked', 'configured',
                        'notcomissioned' or 'integratedtoran'.
        :type variant: str
        :return: dictionary with statuses names as keys and expected statuses values as values
        :rtype: dict(str, str)
        """
        if variant.lower() == 'onair':
            return cls._get_onair_statuses()
        elif variant.lower() == 'test':
            return cls._get_test_statuses()
        elif variant.lower() == 'blocked':
            return cls._get_blocked_statuses()
        elif variant.lower() == 'configured':
            return cls._get_configured_statuses()
        elif variant.lower() == 'notcomissioned':
            return cls._get_notcomissioned_statuses()
        elif variant.lower() == 'integratedtoran':
            return cls._get_integrated_to_ran_statuses()

    @classmethod
    def _get_onair_statuses(cls):
        return {"blockingState": "Unblocked",
                "proceduralState": "OnAir"}

    @classmethod
    def _get_test_statuses(cls):
        return {"blockingState": "Unblocked",
                "proceduralState": "Test"}

    @classmethod
    def _get_blocked_statuses(cls):
        return {"blockingState": "Blocked",
                "proceduralState": "IntegratedToRan"}

    @classmethod
    def _get_configured_statuses(cls):
        return {"blockingState": "Unblocked",
                "proceduralState": "Configured"}

    @classmethod
    def _get_notcomissioned_statuses(cls):
        return {"blockingState": "Unblocked",
                "proceduralState": "NotCommissioned"}

    @classmethod
    def _get_integrated_to_ran_statuses(cls):
        return {"blockingState": "Unblocked",
                "proceduralState": "IntegratedToRan"}
